      <aside class="sidebar">
        <div class="sidebar-header">
          <h1>JP<span>Agents</span></h1>
          <button id="new-chat" class="btn-primary">+ Nuevo Proyecto</button>
        </div>
        <div id="chat-list" class="chat-list">
          <!-- Chat sessions will appear here -->
        </div>
        <div class="sidebar-footer">
          <div class="status-indicator">
            <span class="dot live"></span> Ollama Live
          </div>
        </div>
      </aside>

      <main class="main-content">
        <header class="top-nav">
          <div class="config-group">
            <label>Modelo:</label>
            <select id="model-select">
              <option value="">Cargando modelos...</option>
            </select>
          </div>
          <div class="config-group folder-selector">
            <label>Directorio:</label>
            <input type="text" id="folder-path" placeholder="Pega la ruta de tu carpeta aquí o búscala..." />
            <button id="scan-folder" class="btn-icon" title="Elegir Carpeta">📁</button>
          </div>
        </header>


        <section id="main-view" class="main-view">
          <nav class="tabs-nav" id="tabs-nav">
            <div class="tab active" data-tab="chat">Chat</div>
          </nav>

          <!-- Dashboard View (No tab active) -->
          <div id="dashboard-tab-content" class="tab-content dashboard-view hidden">
            <div class="welcome-screen">
              <div class="dashboard-header">
                <h2 id="dashboard-project-name">Proyecto</h2>
                <p id="dashboard-project-path">Sin carpeta seleccionada</p>
              </div>
              <div class="dashboard-actions">
                <button onclick="window.addChat()" class="btn-primary" style="width: auto; padding-inline: 2rem;">➕ Agregar Nuevo Agente</button>
                <div style="margin: 1rem 0;">o</div>
                <button onclick="document.getElementById('scan-folder').click()" class="btn-primary" style="width: auto; padding-inline: 2rem; background: var(--card-bg); border: 1px solid var(--border-color);">📁 Seleccionar Carpeta</button>
              </div>
              <div class="dashboard-info">
                <h3>Resumen del Proyecto</h3>
                <div class="stats-grid">
                  <div class="stat-card">
                    <span class="stat-value" id="stat-chats">0</span>
                    <span class="stat-label">Agentes</span>
                  </div>
                  <div class="stat-card">
                    <span class="stat-value" id="stat-files">0</span>
                    <span class="stat-label">Archivos Abiertos</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Chat View -->
          <div id="chat-tab-content" class="tab-content hidden">
            <div id="chat-messages" class="chat-messages">
              <!-- Messages appear here -->
            </div>



            <div class="input-area">
              <div id="image-preview-container" class="image-preview-container hidden"></div>
              <div class="input-wrapper">
                <div class="input-actions-left">
                  <button id="attach-img" class="btn-icon-subtle" title="Adjuntar imagen">📷</button>
                  <input type="file" id="image-input" accept="image/*" class="hidden" />
                </div>
                <textarea id="chat-input" placeholder="Escribe una instrucción para el agente..." rows="2"></textarea>
                  <div class="mode-switch-container">
                    <div id="mode-switch-toggle" class="mode-switch auto" title="Alternar Modo: Auto / Supervisado">
                      <div class="mode-switch-handle">
                        <span class="mode-icon-manual">🤖</span>
                      </div>
                    </div>
                  </div>
                  <button id="send-btn" class="send-btn">
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>

          <!-- Editor View -->
          <div id="editor-tab-content" class="tab-content hidden">
            <div class="editor-header">
              <h3 id="current-filename">Archivo.js</h3>
              <div id="pending-actions" class="pending-actions hidden">
                <span class="pending-label">Cambios Propuestos</span>
                <button id="accept-change" class="btn-success">Aceptar ✓</button>
                <button id="reject-change" class="btn-danger">Rechazar ✕</button>
              </div>
            </div>
            <div class="editor-container">
              <pre><code id="editor-code"></code></pre>
            </div>
            <div id="editor-footer" class="editor-footer">
              <div id="diff-stats" class="diff-stats hidden">
                <span class="diff-added">+ 0 agregadas</span>
                <span class="diff-removed">- 0 eliminadas</span>
              </div>
              <div class="editor-info">
                <span id="editor-lang">plaintext</span>
              </div>
            </div>
          </div>
        </section>


      </main>

      <aside class="file-explorer">
        <h3>Archivos del Proyecto</h3>
        <div id="file-list" class="file-list">
          <p class="empty-state">No hay carpeta seleccionada</p>
        </div>
      </aside>
    </div>
    <script type="module" src="/main.js"></script>
  </body>
</html>

