:root {
  --bg-color: #0a0a0c;
  --sidebar-bg: #111114;
  --card-bg: #1a1a1e;
  --accent-color: #7c4dff;
  --accent-gradient: linear-gradient(135deg, #7c4dff 0%, #448aff 100%);
  --text-primary: #e0e0e0;
  --text-secondary: #a0a0a0;
  --border-color: #2a2a2e;
  --glass-bg: rgba(26, 26, 30, 0.8);
  --font-family: 'Outfit', sans-serif;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-primary);
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

#app {
  display: grid;
  grid-template-columns: 260px 1fr 300px;
  height: 100vh;
  width: 100vw;
}

/* Sidebar Styling */
.sidebar {
  background-color: var(--sidebar-bg);
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  padding: 1.5rem;
  height: 100%;
}

.sidebar-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 2rem;
}

.sidebar-header h1 span {
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.btn-primary {
  width: 100%;
  padding: 0.8rem;
  border-radius: 12px;
  border: none;
  background: var(--accent-gradient);
  color: white;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s, opacity 0.2s;
  margin-bottom: 1.5rem;
}

.chat-list {
  flex: 1;
  overflow-y: auto;
}

.chat-item {
  padding: 0.8rem;
  border-radius: 8px;
  margin-bottom: 0.5rem;
  cursor: pointer;
  transition: background 0.2s;
  color: var(--text-secondary);
  font-size: 0.9rem;
  border: 1px solid transparent;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.chat-item.active {
  background: var(--card-bg);
  border-color: var(--accent-color);
  color: var(--text-primary);
}

.session-name { flex: 1; outline: none; cursor: text; padding: 2px 4px; border-radius: 4px; }
.session-name:focus { background: rgba(255,255,255,0.1); }
.dot { margin-left: 10px; width: 8px; height: 8px; background-color: #666; border-radius: 50%;}
.dot.busy { background-color: #ff9800; box-shadow: 0 0 8px #ff9800; animation: pulse 1.5s infinite; }
@keyframes pulse { 0% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.2); } 100% { opacity: 1; transform: scale(1); } }

/* Main Content area */
.main-content {
  display: flex;
  flex-direction: column;
  height: 100vh;
  min-width: 0;
}

.top-nav {
  height: auto;
  min-height: 80px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  padding: 1rem 2rem;
  gap: 2rem;
  flex-wrap: wrap;
}


select, input[type="text"] {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.6rem 1rem;
  border-radius: 10px;
  font-family: inherit;
  font-size: 0.9rem;
  outline: none;
  transition: all 0.2s;
}

select:hover, input[type="text"]:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 2px rgba(124, 77, 255, 0.2);
}

