  align-items: flex-end;
}

.tab {
  padding: 0.6rem 1.2rem;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-bottom: none;
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
