}

/* CHAT MESSAGES SCROLL AREA */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding-right: 10px;
  min-height: 0;
}

.chat-messages::-webkit-scrollbar { width: 6px; }
.chat-messages::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 10px; }

.message {
  max-width: 85%;
  padding: 1rem 1.5rem;
  border-radius: 18px;
  line-height: 1.5;
  word-wrap: break-word;
}

.message.user { align-self: flex-end; background: var(--accent-gradient); color: white; }
.message.agent { align-self: flex-start; background: var(--card-bg); border: 1px solid var(--border-color); }
.message.agent p { margin-bottom: 0.8rem; }
.message.agent p:last-child { margin-bottom: 0; }
.message.agent strong { color: #fff; font-weight: 600; }
.message.agent ul, .message.agent ol { margin-left: 1.2rem; margin-bottom: 0.8rem; }
.message.agent li { margin-bottom: 0.3rem; }
.message.agent h1, .message.agent h2, .message.agent h3 { margin: 1rem 0 0.5rem; color: var(--accent-color); }
.message.agent pre { background: #000; padding: 1rem; border-radius: 8px; margin: 1rem 0; overflow-x: auto; border: 1px solid var(--border-color); }
.message.agent code { font-family: 'Consolas', monospace; background: rgba(0,0,0,0.3); padding: 0.2rem 0.4rem; border-radius: 4px; font-size: 0.9em; }
.message.agent pre code { background: none; padding: 0; }

/* INPUT AREA FIXED AT BOTTOM */
.input-area {
  padding: 1rem 0;
  flex-shrink: 0;
}

textarea {
  flex: 1;
  background: none;
  border: none;
  color: var(--text-primary);
  resize: vertical; /* Permitir resize manual si se desea */
  font-family: inherit;
  font-size: 1rem;
  outline: none;
  min-height: 60px;
  max-height: 200px;
}

/* Multimodal & Input Area Enhancements */
.input-wrapper {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 0.8rem 1rem;
  display: flex;
  align-items: center; /* Alineado al centro para inputs de una línea, pero el textarea crece */
  gap: 1rem;
}

.input-actions-left, .input-actions-right {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.mode-switch-container {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mode-switch {
    position: relative;
    width: 64px;
    height: 32px;
    background: #000;
    border: 1px solid var(--border-color);
    border-radius: 20px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    display: flex;
    align-items: center;
    padding: 2px;
}

.mode-switch::before {
    content: 'AUTO';
    position: absolute;
    right: 8px;
    font-size: 8px;
    font-weight: 800;
    color: var(--text-secondary);
    transition: all 0.3s;
    opacity: 0.7;
}

.mode-switch.supervised::before {
    content: 'SUPV';
    left: 8px;
    right: auto;
}

.mode-switch-handle {
    width: 26px;
    height: 26px;
    background: var(--accent-gradient);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 0 2px 8px rgba(124, 77, 255, 0.4);
    z-index: 2;
}

.mode-switch.supervised .mode-switch-handle {
    transform: translateX(32px);
    background: linear-gradient(135deg, #f44336 0%, #d32f2f 100%);
    box-shadow: 0 2px 8px rgba(244, 67, 54, 0.4);
}

.mode-icon-manual {
    font-size: 14px;
    pointer-events: none;
}

.btn-icon-subtle {
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    width: 40px;
    height: 40px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: all 0.2s;
    flex-shrink: 0;
}

.btn-icon-subtle:hover {
    background: rgba(124, 77, 255, 0.1);
    border-color: var(--accent-color);
    transform: translateY(-2px);
}

.btn-icon-subtle#attach-img {
    color: var(--text-secondary);
}

.btn-icon-subtle#attach-img:hover {
    color: white;
}

.mode-selector-mini {
    display: none; /* Removed the old one */
}

.image-preview-container {
  display: flex;
  gap: 10px;
  padding: 10px;
  background: rgba(0,0,0,0.2);
  border-radius: 12px;
  margin-bottom: 10px;
  overflow-x: auto;
}

.preview-item {
  position: relative;
  width: 60px;
  height: 60px;
}

.preview-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
