  height: 18px;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.send-btn {
  background: var(--accent-gradient);
  border: none;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  color: white;
  cursor: pointer;
}

/* File Explorer */
.file-explorer {
  background-color: var(--sidebar-bg);
  border-left: 1px solid var(--border-color);
  padding: 1.5rem;
  overflow-y: auto;
  height: 100vh;
}

#editor-tab-content {
  background: #0d1117;
  padding: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.editor-header {
  padding: 0.8rem 1.5rem;
  background: #161b22;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.editor-header h3 {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.pending-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.pending-label {
  font-size: 0.8rem;
  background: rgba(255, 152, 0, 0.1);
  color: #ff9800;
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
}

.btn-success, .btn-danger {
  padding: 6px 12px;
  border: none;
  border-radius: 6px;
  color: white;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
}

.btn-success { background: #3fb950; }
.btn-danger { background: #f85149; }
.btn-success:hover, .btn-danger:hover { opacity: 0.8; }

.diff-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  font-weight: 600;
}

