.diff-removed { color: #f85149; }

.editor-container {
  flex: 1;
  overflow: auto;
  position: relative;
}

#editor-code {
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
  font-size: 14px;
  line-height: 1.6;
  padding: 1.5rem;
  display: block;
  white-space: pre;
  word-wrap: normal;
  tab-size: 4;
}

/* Ensure highlight.js tokens are visible */
.hljs {
  color: #e6edf3;
  background: transparent !important;
}

/* Diff Styling */
.diff-line {
  display: block;
  width: 100%;
  padding-left: 0.5rem;
}

.diff-line.added {
  background-color: rgba(63, 185, 80, 0.15);
  border-left: 4px solid #3fb950;
}

.diff-line.removed {
  background-color: rgba(248, 81, 73, 0.15);
  border-left: 4px solid #f85149;
  text-decoration: line-through;
  opacity: 0.8;
}

.diff-marker {
  display: inline-block;
  width: 20px;
  font-weight: bold;
  opacity: 0.7;
  user-select: none;
}

/* Syntax Highlighting Tweaks */
pre code.hljs {
  padding: 0;
  background: transparent;
}

.editor-footer {
  height: 30px;
  background: #161b22;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 1rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.editor-info {
  display: flex;
  gap: 1rem;
}

#editor-lang {
  text-transform: uppercase;
  font-weight: 600;
  color: var(--accent-color);
}
.hidden { display: none !important; }
.message.agent.thinking {
    background: var(--card-bg);
    border: 1px dashed var(--accent-color) !important;
    max-width: 300px;
}

.thinking-bubble-content {
    display: flex;
    align-items: center;
    gap: 12px;
}

.thinking-text-wrapper {
    display: flex;
    flex-direction: column;
}

.thinking-status {
    font-weight: 600;
    font-size: 0.9rem;
    color: white;
}

.thinking-subtext {
    font-size: 0.7rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.spinner-container {
    position: relative;
    width: 20px;
    height: 20px;
}

.spinner {
    width: 20px;
    height: 20px;
    border: 2px solid rgba(124, 77, 255, 0.1);
