    animation: fadeIn 0.5s;
}

.hidden {
    display: none;
}

/* Footer */
footer {
    background-color: var(--color-primary);
    color: white;
    text-align: center;
    padding: 20px;
    margin-top: 40px;
}

/* Media Queries */
@media (max-width: 768px) {
    header h1 {
        font-size: 2.5em;
    }
    .agent-grid, .mushroom-grid {
        gap: 20px;
    }
    .agent-card, .mushroom-card {
        flex-basis: 100%;
    }
}

